WITH ranked AS (SELECT id, ROW_NUMBER() OVER (PARTITION BY LOWER(TRIM(name)) ORDER BY created_at ASC, id ASC) AS rn, FIRST_VALUE(id) OVER (PARTITION BY LOWER(TRIM(name)) ORDER BY created_at ASC, id ASC) AS keeper_id FROM companies), mapping AS (SELECT id AS dup_id, keeper_id FROM ranked WHERE rn > 1), u1 AS (UPDATE company_contacts c SET company_id = m.keeper_id FROM mapping m WHERE c.company_id = m.dup_id RETURNING 1), u2 AS (UPDATE company_activities c SET company_id = m.keeper_id FROM mapping m WHERE c.company_id = m.dup_id RETURNING 1), u3 AS (UPDATE orders o SET company_id = m.keeper_id FROM mapping m WHERE o.company_id = m.dup_id RETURNING 1), u4 AS (UPDATE prospects p SET company_id = m.keeper_id FROM mapping m WHERE p.company_id = m.dup_id RETURNING 1) DELETE FROM companies WHERE id IN (SELECT dup_id FROM mapping); CREATE UNIQUE INDEX IF NOT EXISTS companies_unique_name_norm ON public.companies (LOWER(TRIM(name)));